interaction_patterns_ui <- function(id) { ns<-NS(id); lab_section(c("Notice the feedback that follows an action.","Compare explicit and implicit confirmation.","Choose a pattern that matches the action's consequence."),tagList(p("Experiment · Try each feedback pattern."), fluidRow(column(6, actionButton(ns("inline"),"Save with inline feedback",class="btn-primary"), uiOutput(ns("inline_msg"))), column(6, actionButton(ns("dialog"),"Save with confirmation",class="btn-outline-success")), column(12,uiOutput(ns("dialog_ui")))), p(class="footnote mt-3","These controls demonstrate local interface patterns; no data are saved.")),"When would a confirmation dialog interrupt more than it helps?") }
interaction_patterns_server <- function(id) { moduleServer(id,function(input,output,session){ observeEvent(input$inline,output$inline_msg<-renderUI(div(class="alert alert-success mt-3 mb-0",role="status",paste("Saved ·",format(Sys.time(),"%H:%M:%S"))))); observeEvent(input$dialog,showModal(modalDialog("Your change is ready.","A dialog asks you to acknowledge the result.",easyClose=TRUE,footer=modalButton("Done")))) }) }
